-- migrate:up
CREATE TYPE "user_token_purpose" AS ENUM ('email_verification', 'password_reset');

-- Single-use, expiring tokens handed out by email (verification links,
-- password resets). Only a hash of the token is stored so a leaked database
-- row cannot be replayed as the token itself.
CREATE TABLE "user_tokens" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE,
  "purpose" user_token_purpose NOT NULL,
  "token_hash" bytea UNIQUE NOT NULL,
  "expires_at" timestamp NOT NULL,
  "used_at" timestamp NULL,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE INDEX "user_tokens_user_id_purpose_idx" ON "user_tokens" ("user_id", "purpose");

-- Per-form toggle for the new-submission email; pro plans only, enforced in
-- the application layer.
ALTER TABLE "forms"
  ADD COLUMN "notify_on_submission" boolean NOT NULL DEFAULT false;

-- migrate:down
ALTER TABLE "forms" DROP COLUMN IF EXISTS "notify_on_submission";
DROP INDEX IF EXISTS "user_tokens_user_id_purpose_idx";
DROP TABLE IF EXISTS "user_tokens";
